#include <stddef.h>
#include <stdio.h>

struct BufferView { const unsigned char *data; size_t size; };

int main(void) {
    const unsigned char bytes[] = {0x43, 0x00, 0x4c};
    struct BufferView view = {bytes, sizeof bytes};
    printf("bytes = %zu\n", view.size);
    return 0;
}
